-- 三个管理模块的独立按钮权限；聚合项仅保留字典以兼容旧 API 输入。
-- 复制/默认菜单在首次核验后记录 progress；后续人工撤权、改名、排序、层级或删除不被回填。
-- 使用无别名的集合差探针，遵守现有迁移器禁止限定标识符的 SQL 边界。

-- @step register_button_permissions
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM sys_permission WHERE code IS NOT NULL AND (code,name) IN (('administrators:create', '新增管理员'), ('administrators:update', '修改管理员'), ('administrators:delete', '删除管理员'), ('administrators:reset_password', '重置管理员密码'), ('administrators:assign_roles', '配置管理员角色'), ('roles:create', '新增角色'), ('roles:update', '修改角色'), ('roles:delete', '删除角色'), ('roles:permissions', '设置角色权限'), ('menus:read', '查看菜单'), ('menus:create', '新增菜单'), ('menus:update', '修改菜单'), ('menus:delete', '删除菜单')))=13 THEN 1 ELSE 0 END AS complete;
INSERT INTO sys_permission (code, name) VALUES ('administrators:create', '新增管理员'), ('administrators:update', '修改管理员'), ('administrators:delete', '删除管理员'), ('administrators:reset_password', '重置管理员密码'), ('administrators:assign_roles', '配置管理员角色'), ('roles:create', '新增角色'), ('roles:update', '修改角色'), ('roles:delete', '删除角色'), ('roles:permissions', '设置角色权限'), ('menus:read', '查看菜单'), ('menus:create', '新增菜单'), ('menus:update', '修改菜单'), ('menus:delete', '删除菜单') ON DUPLICATE KEY UPDATE name=VALUES(name);

-- @step copy_legacy_management_grants
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM schema_migration WHERE migration_id='036_role_menu_button_permissions' AND status IN ('applied','applying','failed') AND progress LIKE '%"copy_legacy_management_grants"%') OR (NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:create'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:update'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:delete'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:reset_password'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:assign_roles'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:create'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:update'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:delete'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:permissions'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:read') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:read'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:create'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:update'))) AND NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write') AND role_id NOT IN (SELECT role_id FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='menus:delete')))) THEN 1 ELSE 0 END AS complete;
INSERT IGNORE INTO sys_role_permission (role_id, permission_id)
SELECT role_id, (SELECT id FROM sys_permission WHERE code='administrators:create') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='administrators:update') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write')
