UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='administrators:assign_roles') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='administrators:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='roles:create') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='roles:update') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='roles:delete') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='roles:permissions') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='roles:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='menus:read') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:read')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='menus:create') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write')
UNION ALL
SELECT role_id, (SELECT id FROM sys_permission WHERE code='menus:update') FROM sys_role_permission WHERE permission_id=(SELECT id FROM sys_permission WHERE code='system_settings:write')
