-- @step remove_aggregate_role_grants
-- @check SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code IN ('administrators:write','roles:write'))) THEN 1 ELSE 0 END AS complete;
DELETE FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code IN ('administrators:write','roles:write'));

-- @step bind_menu_read_permission
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM schema_migration WHERE migration_id='036_role_menu_button_permissions' AND status IN ('applied','applying','failed') AND progress LIKE '%"bind_menu_read_permission"%') OR NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/system/menus' AND (permission_code IS NULL OR permission_code<>'menus:read')) THEN 1 ELSE 0 END AS complete;
UPDATE sys_menu SET permission_code='menus:read' WHERE type='menu' AND route_path='/admin/system/menus';

-- @step seed_management_buttons
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM schema_migration WHERE migration_id='036_role_menu_button_permissions' AND status IN ('applied','applying','failed') AND progress LIKE '%"seed_management_buttons"%') OR (NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/administrators' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='administrators:create' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/administrators' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='administrators:update' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/administrators' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='administrators:delete' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/administrators' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='administrators:reset_password' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/administrators' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='administrators:assign_roles' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/roles' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='roles:create' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/roles' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='roles:update' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/roles' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='roles:delete' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/roles' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='roles:permissions' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/system/menus' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='menus:create' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/system/menus' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='menus:update' AND parent_id IS NOT NULL)) AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE type='menu' AND route_path='/admin/system/menus' AND id NOT IN (SELECT parent_id FROM sys_menu WHERE type='button' AND permission_code='menus:delete' AND parent_id IS NOT NULL))) THEN 1 ELSE 0 END AS complete;
INSERT IGNORE INTO sys_menu (parent_id, name, type, route_path, permission_code, icon, sort, status)
